cat > /tmp/fix.py <<'EOF'
p='out/transform.ts'
s=open(p).read()
a=s.index('  for (const e of all) if (e.row.type === "VITAL")')
b=s.index('\n',a)
s=s[:a]+'''  for (const e of all) {
    if (e.row.type !== "VITAL") continue;
    const k = e.item.id + "|" + e.row.VISIT_ID;
    const l = byVisit.get(k) ?? [];
    l.push(e);
    byVisit.set(k, l);
  }'''+s[b:]
open(p,'w').write(s)
EOF
python3 -I /tmp/fix.py; sh in/harness/check.sh 2>&1 | grep -E "error|\"vitals\"|local_time|collected" | head -30
